sys_ui_action.script:
// bfd_ui_retriage_case — force the AI assessment to be regenerated after an
// agent has corrected the case facts. force:true overwrites the previously
// derived intent / risk / urgency / priority / recommendation values.
(function retriageCaseAction() {
    var CASE_TABLE = 'x_1755386_safetr_0_bfd_fraud_dispute_case';
    var caseId = current.getUniqueValue();
    var engine = new bfd_TriageEngine();

    var before = {
        risk_level: current.getValue('risk_level') || '(empty)',
        risk_score: current.getValue('risk_score') || '0',
        priority: current.getValue('priority') || '(empty)',
        intent: current.getValue('intent_classification') || '(empty)',
    };

    var out = engine.triageCaseAndUpdate(caseId, { force: true });

    if (!out) {
        gs.addErrorMessage('Re-triage could not be run for this case.');
        action.setRedirectURL(current);
        return;
    }

    var gr = new GlideRecord(CASE_TABLE);
    if (!gr.get(caseId)) {
        gs.addErrorMessage('Re-triage completed but the case could not be re-read.');
        action.setRedirectURL(current);
        return;
    }

    engine.logAiDecision(gr, {
        recommendation: out.recommendation,
        note:
            'Agent ' +
            gs.getUserDisplayName() +
            ' forced a re-triage after editing the case facts. Previous values — intent: ' +
            before.intent +
            ', risk: ' +
            before.risk_level +
            ' (' +
            before.risk_score +
            '), priority: ' +
            before.priority +
            '.',
        finalDecision: 'retriage_forced',
    });
    gr.update();

    gs.addInfoMessage(
        'AI assessment regenerated. Risk is now ' +
            (gr.getValue('risk_level') || 'unknown') +
            ' (' +
            (gr.getValue('risk_score') || '0') +
            '/100), priority ' +
            (gr.getValue('priority') || 'unknown') +
            '. The override is recorded in the audit trail.'
    );
    action.setRedirectURL(current);
})();
